    public static void testANumberAloneAtTheFootOf_everyPageIsAPageNumber() {
        emon.Port.Cells wd = emon.Port.newCells();
        emon.Port.Cells ln = emon.Port.newCells();
        emon.Port.Cells et = emon.Port.newCells();
        emon.Port.Cells txt = emon.Port.newCells();
        emon.Port.Cells md = emon.Port.newCells();
        emon.Port.Cells lb = emon.Port.newCells();
        StringBuilder t1 = emon.Testport.newText();
        StringBuilder t2 = emon.Testport.newText();
        StringBuilder t3 = emon.Testport.newText();
        // Four pages, a bare number centred in the bottom margin: dropped from the flow, kept as the page's label.
        flPages(wd, ln, et, 4);
        flBottom(wd, ln, et, emon.Testport.textBlob("1"), 1, 30000, 31000);
        flBottom(wd, ln, et, emon.Testport.textBlob("2"), 2, 30000, 31000);
        flBottom(wd, ln, et, emon.Testport.textBlob("3"), 3, 30000, 31000);
        flBottom(wd, ln, et, emon.Testport.textBlob("4"), 4, 30000, 31000);
        emon.Testport.assertEq(flRun(wd, ln, et, 4, 0, 0, txt, md, lb, t1), 0, "number: well formed");
        emon.Testport.assertText(t1, "L1=1;L2=2;L3=3;L4=4;Dp@1:1;Dp@2:2;Dp@3:3;Dp@4:4;P:alpha beta. |alpha beta. |alpha beta. |alpha beta.;", "page numbers: labels, ledger rows, and not a word of them in the body");
        // `keep`: nothing leaves the flow (the labels of /PageLabels would still come, but there are none).
        emon.Testport.assertEq(flRun(wd, ln, et, 4, 0, 1, txt, md, lb, t2), 0, "keep: well formed");
        emon.Testport.assertText(t2, "P:alpha beta.;P:1;P:alpha beta.;P:2;P:alpha beta.;P:3;P:alpha beta.;P:4;", "keep: every line stays where it was");
        // `drop` takes the same here: a page number is dropped by the policy too.
        emon.Testport.assertEq(flRun(wd, ln, et, 4, 0, 2, txt, md, lb, t3), 0, "drop: well formed");
        emon.Testport.assertText(t3, "L1=1;L2=2;L3=3;L4=4;Dp@1:1;Dp@2:2;Dp@3:3;Dp@4:4;P:alpha beta. |alpha beta. |alpha beta. |alpha beta.;", "drop: the same");
    }
