    public static int flRoots(emon.Port.Cells nodes) {
        // How many `furniture` roots the Model has.
        int nn = Model.nodeCount(nodes);
        int i = 0;
        int n = 0;
        while (i < nn) {
            if ((Model.nodeKind(nodes, i) == Model.nkFurniture()) && (Model.nodeParent(nodes, i) == -1)) {
                n += 1;
            }
            i += 1;
        }
        return n;
    }
